/// Translations share stable English seed keys; category identity still includes kind and parent.
/// Every translated row is provisional until reviewed by a native speaker.
enum StarterCategoryNames {
  /// Unicode case folding also equates expanded capitals, such as Armenian ligatures.
  static func searchKey(_ name: String) -> String {
    NameKey.fold(name.folding(options: .caseInsensitive, locale: Locale(identifier: "en_US_POSIX")))
  }

  static func name(english: String, language: StarterLanguage) -> String? {
    names[language]?[english]
  }

